"""Example routes on the demo area, generated by the package's own Router, loop generator, rating and cue sheet.

These are what the static site shows as "computed by Python": A->B alternatives between the area's hubs (its
centre and the largest named parks, chosen by routing.catalog.pick_hubs when the demo was exported) and suggested
loops from the centre, the same recipe as routing.catalog.build_catalog with distances that fit the small demo area.
"""
from functools import lru_cache

from cycleroutes.api.serialize import profile_label
from cycleroutes.routing.context import RouteContext
from cycleroutes.routing.directions import cue_sheet
from cycleroutes.routing.loops import generate_loops
from cycleroutes.routing.rating import rate
from cycleroutes.routing.route import Route
from cycleroutes.routing.router import Router, RoutingError
from cycleroutes.web import demo_area

LOOP_PROFILES = ("scenic", "family", "balanced")   # catalog.DEFAULT_PROFILES (catalog imports the GIS stack)
LOOP_DISTANCES_KM = (4, 7)      # the demo area is ~3 km across; build_catalog's 8/15/25 km would not fit
MAX_JOURNEYS = 3


def route_json(route: Route, stats: dict, **extra) -> dict:
    """Compact payload: edge triples (the browser draws them from the demo graph), stats, cue sheet."""
    return {"profile": route.profile, "profile_label": profile_label(route.profile), "kind": route.kind,
            "also_best_for": [profile_label(p) for p in route.meta.get("also_matches", [])],
            "edges": [[int(u), int(v), int(k)] for u, v, k in route.edges], "stats": stats,
            "cues": [c.to_dict() for c in cue_sheet(route)], **extra}


def alternatives_json(router: Router, start, end, ctx: RouteContext) -> list[dict]:
    routes = router.alternatives(tuple(start), tuple(end), ctx=ctx)
    fastest = min(r.time_s for r in routes)
    return [route_json(r, rate(r, fastest_time_s=fastest)) for r in routes]


def loops_json(router: Router, start, km: float, profile: str, count: int, ctx: RouteContext) -> list[dict]:
    return [route_json(loop, stats) for loop, stats in generate_loops(router, tuple(start), km, profile, count, ctx)]


@lru_cache(maxsize=1)
def examples() -> dict:
    demo = demo_area.load_demo()
    router = Router(demo_area.load_graph())
    hubs = demo["area"]["hubs"]
    ctx = RouteContext()
    journeys = []
    for a, b in list(zip(hubs, hubs[1:]))[:MAX_JOURNEYS]:
        start, end = [a["lat"], a["lon"]], [b["lat"], b["lon"]]
        journeys.append({"title": f"{a['name']} to {b['name']}", "start": start, "end": end,
                         "routes": alternatives_json(router, start, end, ctx)})
    loops = []
    centre = hubs[0]
    for km in LOOP_DISTANCES_KM:
        for profile in LOOP_PROFILES:
            try:
                (loop, stats), = generate_loops(router, (centre["lat"], centre["lon"]), km, profile, count=1, ctx=ctx)
            except RoutingError:
                continue
            loops.append(route_json(loop, stats, title=f"{centre['name']}: {stats['distance_km']:.0f} km "
                                    f"{profile_label(profile).lower()} loop", target_km=km,
                                    start=[centre["lat"], centre["lon"]]))
    return {"area": demo["area"]["title"], "journeys": journeys, "loops": loops,
            "method": {"loop_distances_km": list(LOOP_DISTANCES_KM), "loop_profiles": list(LOOP_PROFILES)}}
